pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = address(0xc0de);

        // Deploy mock ERC20 for collateral and debt (simplified: use address(this) as token)
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        // we need a cooler that will request a loan; since the contract's owner() is used in clearRequest/rescind
        // but the test only needs to distinguish owner() identity via rescindRequest revert

        // First: create a request as the owner so there is something to rescind
        // But we don't have a real ERC20, so we can't transfer tokens.
        // Instead, test the core difference: owner() returns 0 vs address(0xc0de).
        // The buggy version returns address(0) for owner. The correct version returns the immutable arg.
        // rescindRequest requires msg.sender == owner(). So we call as 0xc0de:
        vm.prank(owner);
        // In correct version, c.owner() == 0xc0de => call succeeds (but will revert due to no request; that's fine)
        // In buggy version, c.owner() == address(0) => call reverts because msg.sender != address(0)
        // We catch the revert:
        bool ok;
        try c.rescindRequest(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // The correct version (owner returns 0xc0de) will revert because request 0 doesn't exist; so ok==false
        // The buggy version (owner returns 0) will revert because msg.sender != owner; also ok==false
        // So we need a different observable: use a getter that returns owner():
        address own = c.owner();
        // In correct version: own == 0xc0de; in buggy: own == address(0)
        // Assert that the correct version holds (the bug breaks this assertion):
        assertTrue(own != address(0));
