        vm.etch(collateral, erc20Code);
        vm.etch(debt, erc20Code);

        // Set up owner
        address owner = address(0xdead);
        vm.deal(owner, 1 ether);

        // Fund owner with collateral and debt tokens
        // We'll just give them 1000 tokens of each
        bytes memory fundCollateral = abi.encodeWithSignature("transferFrom(address,address,uint256)", owner, address(c), 1000);
        (bool success,) = collateral.call(fundCollateral);
        require(success, "fund collateral failed");

        bytes memory fundDebt = abi.encodeWithSignature("transferFrom(address,address,uint256)", owner, address(c), 1000);
        (success,) = debt.call(fundDebt);
        require(success, "fund debt failed");

        // Owner requests a loan
        vm.startPrank(owner);
        c.requestLoan(100, 1e16, 2, 7 days);
        vm.stopPrank();

        // Non-owner lender clears the request
        address lender = address(0xbeef);
        vm.prank(lender);
        (uint256 loanID) = c.clearRequest(0, false, false);

        // Now a non-owner, non-lender address (attacker) tries to approveTransfer
        address attacker = address(0x1337);
        vm.prank(attacker);

        bool ok;
        try c.approveTransfer(lender, loanID) {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference: reverts (ok == false), so approvals stays 0
        // In bug: succeeds (ok == true), so approvals[loanID] becomes lender
        // Assert that ok is false (reference behavior), which bug breaks
        assertTrue(!ok, "approveTransfer should revert for non-lender");
    }
}

